body.script:
// Faster loading experience
document.addEventListener('DOMContentLoaded', function() {
  // Mark as loaded sooner
  setTimeout(function() {
    document.body.classList.add('is-loaded');
  }, 300); // Reduce delay from 300ms to 100ms
});

(function() {
  let mouseoverTimer;
  let lastTouchTimestamp;
  const prefetches = new Set();
  const prefetchElement = document.createElement('link');
  const isSupported = prefetchElement.relList && prefetchElement.relList.supports && prefetchElement.relList.supports('prefetch');

  if (!isSupported) return;

  const allowQueryString = 'instantAllowQueryString' in document.body.dataset;
  const allowExternalLinks = 'instantAllowExternalLinks' in document.body.dataset;

  const useWhitelist = 'instantWhitelist' in document.body.dataset;
  const mousedownShortcut = 'instantMousedownShortcut' in document.body.dataset;
  const DELAY_TO_NOT_BE_CONSIDERED_A_TOUCH_INITIATED_ACTION = 1111;

  let delayOnHover = 65;
  let useMousedown = false;
  let useMousedownOnly = false;
  let useViewport = false;

  if ('instantIntensity' in document.body.dataset) {
    const intensity = document.body.dataset.instantIntensity;

    if (intensity.substr(0, 'mousedown'.length) == 'mousedown') {
      useMousedown = true;
      if (intensity == 'mousedown-only') {
        useMousedownOnly = true;
      }
    }
    else if (intensity.substr(0, 'viewport'.length) == 'viewport') {
      useViewport = true;
    }
    else if (intensity == 'hover') {
      delayOnHover = 0;
    }
    else {
      const milliseconds = parseInt(intensity);
      if (!isNaN(milliseconds)) {
        delayOnHover = milliseconds;
      }
    }
  }

  if (useMousedownOnly) {
    useMousedown = false;
  }

  const eventListenersOptions = {
    capture: true,
    passive: true,
  };

  const isUrlSameAsCurrent = (url) => {
    return url.origin == location.origin && url.pathname == location.pathname && url.search == location.search;
  };

  const getUrlFromLinkElement = (linkElement) => {
    return new URL(linkElement.href, location.href);
  };

  const isPreloadable = (linkElement) => {
    if (!linkElement || !linkElement.href) {
      return false;
    }

    if (useWhitelist && !('instant' in linkElement.dataset)) {
      return false;
    }

    if (!allowExternalLinks && linkElement.origin != location.origin && !('instant' in linkElement.dataset)) {
      return false;
    }

    if (!['http:', 'https:'].includes(linkElement.protocol)) {
      return false;
    }

    if (linkElement.protocol == 'http:' && location.protocol == 'https:') {
      return false;
    }

    if (!allowQueryString && linkElement.search && !('instant' in linkElement.dataset)) {
      return false;
    }

    if (linkElement.hash && linkElement.pathname + linkElement.search == location.pathname + location.search) {
      return false;
    }

    if ('noInstant' in linkElement.dataset) {
      return false;
    }

    return true;
  };

  const preload = (url) => {
    if (prefetches.has(url.href)) {
      return;
    }

    const prefetcher = document.createElement('link');
    prefetcher.rel = 'prefetch';
    prefetcher.href = url.href;
    document.head.appendChild(prefetcher);

    prefetches.add(url.href);
  };

  const touchendListener = (event) => {
    lastTouchTimestamp = performance.now();
    const linkElement = event.target.closest('a');
    if (!isPreloadable(linkElement)) {
      return;
    }
    preload(getUrlFromLinkElement(linkElement));
  };

  const mouseoverListener = (event) => {
    if (performance.now() - lastTouchTimestamp < DELAY_TO_NOT_BE_CONSIDERED_A_TOUCH_INITIATED_ACTION) {
      return;
    }

    const linkElement = event.target.closest('a');
    if (!isPreloadable(linkElement)) {
      return;
    }

    linkElement.addEventListener('mouseout', mouseoutListener, {passive: true});

    mouseoverTimer = setTimeout(() => {
      preload(getUrlFromLinkElement(linkElement));
      mouseoverTimer = undefined;
    }, delayOnHover);
  };

  const mousedownListener = (event) => {
    const linkElement = event.target.closest('a');
    if (!isPreloadable(linkElement)) {
      return;
    }
    preload(getUrlFromLinkElement(linkElement));
  };

  const mouseoutListener = (event) => {
    if (mouseoverTimer) {
      clearTimeout(mouseoverTimer);
      mouseoverTimer = undefined;
    }
  };

  document.addEventListener('touchstart', touchendListener, eventListenersOptions);
  document.addEventListener('mousedown', mousedownListener, eventListenersOptions);

  if (!useMousedownOnly) {
    document.addEventListener('mouseover', mouseoverListener, eventListenersOptions);
  }
})();

document.addEventListener("DOMContentLoaded", function() {
  document.querySelectorAll('form[action*="/cart/add"]').forEach(function(form) {
    form.addEventListener('submit', function () {
      if (typeof fbq === 'function') {
        fbq('track', 'AddToCart');
      }
    });
  });
});

document.addEventListener("DOMContentLoaded", function () {
  const popup = document.getElementById("holiday-popup");
  const closeBtn = document.getElementById("popup-close");

  // Date range: show popup from now until Jan 2, 2026
  const now = new Date();
  const startDate = new Date(); // now
  const endDate = new Date(2026, 0, 2); // January 2, 2026 (month 0 = Jan)

  // Only show on homepage, within date range, and if not already dismissed
  if (
    window.location.pathname === "/" &&
    now >= startDate &&
    now <= endDate &&
    !sessionStorage.getItem("holidayDismissed")
  ) {
    popup.style.display = "block";
  }

  // Close button logic
  closeBtn.addEventListener("click", function () {
    popup.style.display = "none";
    sessionStorage.setItem("holidayDismissed", "true"); // won't show again this session
  });
});

